function clampDirectoryColumnWidthPx(px: number): number {
  return Math.max(
    DIRECTORY_COLUMN_WIDTH_MIN_PX,
    Math.min(DIRECTORY_COLUMN_WIDTH_MAX_PX, Math.round(px))
  )
}
